/* ── this-is-jac flourishes ─────────────────────────────────────────── */

/* subtle dotted grid backdrop used behind hero / sections */
.tij-grid {
    background-image: radial-gradient(
        var(--color-border) 1px,
        transparent 1px
    );
    background-size: 26px 26px;
    mask-image: radial-gradient(ellipse 80% 60% at 50% 0%, #000 40%, transparent 100%);
}

/* warm radial glow */
.tij-glow {
    background: radial-gradient(
        ellipse 60% 50% at 50% 0%,
        color-mix(in oklch, var(--jac) 26%, transparent),
        transparent 70%
    );
}

.tij-gradient-text {
    background-image: linear-gradient(110deg, var(--jac-2), var(--jac));
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
}

@keyframes tij-fade-up {
    from { opacity: 0; transform: translateY(14px); }
    to { opacity: 1; transform: translateY(0); }
}
@keyframes tij-pulse {
    0%, 100% { opacity: 0.55; }
    50% { opacity: 1; }
}
@keyframes tij-bounce-down {
    0%, 100% { transform: translateY(0); opacity: 0.5; }
    50% { transform: translateY(6px); opacity: 1; }
}

.tij-fade-up { animation: tij-fade-up 0.6s ease both; }
.tij-pulse { animation: tij-pulse 1.6s ease-in-out infinite; }
.tij-bounce { animation: tij-bounce-down 1.8s ease-in-out infinite; }

/* flowing dashes along the interop funnel connectors */
@keyframes tij-flow { to { stroke-dashoffset: -16; } }
.tij-flow { stroke-dasharray: 5 7; animation: tij-flow 0.9s linear infinite; }

/* thin custom scrollbar */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: oklch(1 0 0 / 0.1); border-radius: 8px; }
::-webkit-scrollbar-thumb:hover { background: oklch(1 0 0 / 0.18); }

/* ── littleX (embedded app) flourishes ───────────────────────────────── */

@keyframes fadeUp {
    from { opacity: 0; transform: translateY(6px); }
    to { opacity: 1; transform: translateY(0); }
}
@keyframes pulse-dot {
    0%, 100% { opacity: 0.5; }
    50% { opacity: 1; }
}

.lx-fade-up { animation: fadeUp 0.3s ease both; }
.lx-pulse { animation: pulse-dot 1.2s ease-in-out infinite; }

.lx-char-ring { width: 22px; height: 22px; flex-shrink: 0; }
.lx-char-ring-bg { fill: none; stroke: var(--border); stroke-width: 2.5; }
.lx-char-ring-fill {
    fill: none;
    stroke-width: 2.5;
    stroke-linecap: round;
    transform: rotate(-90deg);
    transform-origin: 12px 12px;
    transition: stroke-dashoffset 0.12s ease, stroke 0.2s ease;
}

